import re

def post_process(text):
    if not text:
        return ""
    if "```" in text:
        blocks = re.findall(r"```(.*?)```", text, re.DOTALL)
        if not blocks:
            raw_blocks = [text.split("```", 1)[1]]
        else:
            raw_blocks = blocks
        cleaned_blocks = []
        for b in raw_blocks:
            b = re.sub(r"^\s*(?:python3?|py)\b[ \t]*\r?\n?", "", b, flags=re.IGNORECASE)
            b = b.replace("\\n", "\n")
            cleaned_blocks.append(b)
        non_trivial = [
            b for b in cleaned_blocks
            if any(line.strip() and not line.strip().startswith("#") for line in b.splitlines())
        ]
        if non_trivial:
            # Prefer a block containing def/class/import/input/print/for/while/return
            code_blocks = [
                b for b in non_trivial
                if re.search(r"\b(def|class|import|from|input|print|return|for|while|if)\b", b)
            ]
            text = code_blocks[-1] if code_blocks else non_trivial[-1]
        else:
            text = cleaned_blocks[-1]
    else:
        text = re.sub(r"^\s*(?:python3?|py)\b[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
        text = text.replace("\\n", "\n")
    return text

for sample_str in [
