from __future__ import annotations

import ast
import faulthandler
import json
import multiprocessing
import os
import platform
import re
import signal
import sys
import types
from datetime import datetime
from enum import Enum
from io import StringIO
from unittest.mock import mock_open, patch

import numpy as np

try:
    from pyext import RuntimeModule
except ImportError:
    RuntimeModule = None

class _FallbackRuntimeModule:
    @staticmethod
    def from_string(name, _doc, code):
        module = types.ModuleType(name)
        exec(compile(code, name, "exec"), module.__dict__)
        return module

def _runtime_module():
    return RuntimeModule if RuntimeModule is not None else _FallbackRuntimeModule

TIMEOUT = 10
_FAIL_LOG_N = int(os.environ.get("TACO_FAIL_LOG_N", "2"))
_DEBUG_CLIP = 800

def _fix_literal_newlines(code: str) -> str:
    code = re.sub(r"(?m)^([ \t]*)\\n[ \t]*", r"\1", code)
    code = re.sub(r"\\n(?=\s*#?\s*Use (?:Call-Based|Standard Input) format)", "\n", code)
    return code

def post_process(text):
    if not text:
        return ""
    if "```" in text:
        blocks = re.findall(r"```(.*?)```", text, re.DOTALL)
        if not blocks:
            raw_blocks = [text.split("```", 1)[1]]
        else:
            raw_blocks = blocks
        cleaned_blocks = []
        for b in raw_blocks:
            b = re.sub(r"^\s*(?:python3?|py)\b[ \t]*\r?\n?", "", b, flags=re.IGNORECASE)
            b = _fix_literal_newlines(b)
            cleaned_blocks.append(b)
        non_trivial = [
            b for b in cleaned_blocks
            if any(line.strip() and not line.strip().startswith("#") for line in b.splitlines())
        ]
        if non_trivial:
            code_blocks = [
                b for b in non_trivial
                if re.search(r"\b(def|class|import|from|input|print|return|for|while|if)\b", b)
            ]
            text = code_blocks[-1] if code_blocks else non_trivial[-1]
        else:
            text = cleaned_blocks[-1]
    else:
        text = re.sub(r"^\s*(?:python3?|py)\b[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
        text = _fix_literal_newlines(text)
    return text

def _clean_call_based_ast(code: str) -> str:
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return code
    has_def_or_class = any(
        isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) for n in tree.body
    )
    if not has_def_or_class:
        return code
    new_body = []
    for node in tree.body:
        if isinstance(
            node,
            (
                ast.Import,
                ast.ImportFrom,
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
                ast.Assign,
                ast.AnnAssign,
                ast.AugAssign,
            ),
        ):
            new_body.append(node)
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
            new_body.append(node)
    tree.body = new_body
    ast.fix_missing_locations(tree)
    try:
        return ast.unparse(tree)
    except Exception:
        return code

def _parse_ground_truth(ground_truth):
    if isinstance(ground_truth, dict):
        return ground_truth
    if not isinstance(ground_truth, str):
        ground_truth = str(ground_truth)
    return json.loads(ground_truth)

def _to_bool_results(raw):
    fixed = []
    for e in raw:
        if isinstance(e, np.ndarray):
            e = e.item(0) if e.size else False
        if isinstance(e, np.bool_):
            e = bool(e)
        fixed.append(e)
    return fixed

def _clip_debug(obj, limit=_DEBUG_CLIP):
    if obj is None:
        return None
    if isinstance(obj, str):
        text = obj
    else:
        try:
            text = json.dumps(obj, ensure_ascii=False, default=str)
        except Exception:
            text = repr(obj)
    if len(text) > limit:
        return text[:limit] + f"...[+{len(text) - limit} chars]"
    return text

def _fill_fail_debug(box, **kwargs):
    if box is None or box:
        return
    for key, value in kwargs.items():
        if key in {"input", "expected", "output", "code", "error", "prompt"}:
            value = _clip_debug(value)
        box[key] = value

def _run_all_tests(solution_str, ground_truth, extra_info=None):

    extra_info = extra_info or {}
    code = post_process(solution_str)
    in_outs = _parse_ground_truth(ground_truth)
    sample = {"input_output": json.dumps(in_outs)}
    n_cases = len(in_outs.get("inputs") or [])
    timeout = min(max(TIMEOUT, 2 * max(n_cases, 1) + 1), 15)
    raw, fail_debug = check_correctness(sample, code, timeout=timeout, debug=False)
    results = _to_bool_results(raw)
    n_pass = sum(1 for r in results if r is True)
    if fail_debug is None:
        fail_debug = {}
    if any(r is not True for r in results) and not fail_debug:
        fail_idx = next((i for i, r in enumerate(results) if r is not True), 0)
        fail_debug = {
            "result": results[fail_idx] if results else -1,
            "fail_index": fail_idx,
            "error": "no_per_case_debug",
        }
    if fail_debug:
        fail_debug.setdefault("code", _clip_debug(code, 1200))
        fail_debug.setdefault("n_tests", n_cases)
        fail_debug.setdefault("n_pass", n_pass)
        if isinstance(extra_info, dict):
            fail_debug.setdefault("problem_id", extra_info.get("problem_id"))
            fail_debug.setdefault("code_type", extra_info.get("code_type"))
            fail_debug.setdefault("fn_name", extra_info.get("fn_name") or in_outs.get("fn_name"))
        return results, fail_debug
    return results, None

def _summarize(results):
    n = len(results) if results else 0
    if n == 0:
        return 0.0, 0.0
    n_pass = sum(1 for r in results if r is True)
    pass_rate = n_pass / n
    binary = 1.0 if n_pass == n else 0.0
    return float(pass_rate), float(binary)

def compute_score_pass_rate(solution_str, ground_truth, extra_info=None, **kwargs):

    results, _ = _run_all_tests(solution_str, ground_truth, extra_info)
    pass_rate, _ = _summarize(results)
    return pass_rate

def compute_score_binary(solution_str, ground_truth, extra_info=None, **kwargs):

    results, _ = _run_all_tests(solution_str, ground_truth, extra_info)
    _, binary = _summarize(results)
    return binary

def _is_validate(extra_info):
    if not isinstance(extra_info, dict):
        return False
    if extra_info.get("validate"):
        return True
    return extra_info.get("split") == "test"

def compute_score(solution_str=None, ground_truth=None, extra_info=None, data_source=None, **kwargs):

    if solution_str is None:
        solution_str = kwargs.get("completion") or kwargs.get("generation") or ""
    results, fail_debug = _run_all_tests(solution_str, ground_truth, extra_info)
    pass_rate, binary = _summarize(results)
    if _is_validate(extra_info):
        score = binary
    else:
        score = 0.5 * binary + 0.5 * pass_rate
    return {
        "score": float(score),
        "acc": float(binary),
        "pass_rate": float(pass_rate),
        "fail_debug": fail_debug,
    }

def _question_for_log(prompt):
    if not prompt:
        return None
    text = str(prompt)
    if "QUESTION:" in text:
        text = "QUESTION:" + text.split("QUESTION:", 1)[1]
    if "\nANSWER:" in text:
        text = text.split("\nANSWER:", 1)[0]
    return _clip_debug(text, 800)

def _code_for_log(code):
    if not code:
        return code
    text = str(code).lstrip()
    if text.lower().startswith("python"):
        text = text[6:].lstrip("\n")
    return _clip_debug(text, 1200)

def log_taco_failures(fail_debug_list, *, prompts=None, tag="train", step=None, n=None):

    limit = _FAIL_LOG_N if n is None else n
    printed = 0
    for i, dbg in enumerate(fail_debug_list or []):
        if not dbg:
            continue
        print("=" * 72, flush=True)
        print(f"[TACO-FAIL] split={tag} step={step} idx={i}", flush=True)
        print(f"  problem_id={dbg.get('problem_id')} code_type={dbg.get('code_type')} fn_name={dbg.get('fn_name')}", flush=True)
        print(f"  n_pass/n_tests={dbg.get('n_pass')}/{dbg.get('n_tests')} fail_index={dbg.get('fail_index')} result={dbg.get('result')}", flush=True)
        if prompts is not None and i < len(prompts) and prompts[i]:
            print(f"[question] {_question_for_log(prompts[i])}", flush=True)
        if dbg.get("error"):
            print(f"[error] {dbg.get('error')}", flush=True)
        print(f"[code] {_code_for_log(dbg.get('code'))}", flush=True)
        print(f"[input] {dbg.get('input')}", flush=True)
        print(f"[expected] {dbg.get('expected')}", flush=True)
        print(f"[output] {dbg.get('output')}", flush=True)
        printed += 1
        if printed >= limit:
            break
    if printed:
        print("=" * 72, flush=True)

def _temp_run(sample, generation, debug, conn):

    try:
        fail_debug = {}
        results = run_test(sample, test=generation, debug=debug, fail_debug=fail_debug)
        conn.send((list(results), dict(fail_debug) if fail_debug else None))
    except Exception as exc:
        try:
            conn.send(([-1], {"result": -1, "error": f"child: {exc!r}", "fail_index": 0}))
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass
        os._exit(0)

class _ResultList(list):

    def __init__(self, fail_debug, ctx):
        super().__init__()
        self._fail_debug = fail_debug
        self._ctx = ctx

    def append(self, item):
        super().append(item)
        if item is not True:
            _fill_fail_debug(
                self._fail_debug,
                result=item,
                fail_index=self._ctx["index"],
                input=self._ctx["inputs"],
                expected=self._ctx["expected"],
                output=self._ctx["output"],
                error=self._ctx["error"],
            )

def check_correctness(sample, generation, timeout, debug=True):

    recv_conn, send_conn = multiprocessing.Pipe(duplex=False)
    p = multiprocessing.Process(target=_temp_run, args=(sample, generation, debug, send_conn))
    p.start()
    send_conn.close()
    payload = None
    try:
        if recv_conn.poll(timeout + 1):
            payload = recv_conn.recv()
    except Exception:
        payload = None
    finally:
        recv_conn.close()
    p.join(timeout=1)
    if p.is_alive():
        p.kill()
        p.join(timeout=1)
    if payload is None:
        in_outs = json.loads(sample["input_output"])
        n = len(in_outs.get("inputs") or [])
        if debug:
            print("global timeout")
        return [-1 for _ in range(n)], {"result": -1, "error": "global_timeout", "fail_index": 0}
    if isinstance(payload, tuple) and len(payload) == 2:
        return payload[0], payload[1]
    return payload, None

class CODE_TYPE(Enum):
    call_based = 0
    standard_input = 1

class TimeoutException(Exception):
    pass

def timeout_handler(signum, frame):
    if False:
        print('alarm went off')
    raise TimeoutException

def _install_sigalrm():

    try:
        signal.signal(signal.SIGALRM, timeout_handler)
    except (AttributeError, ValueError):
        pass

timeout = 2

class Capturing(list):

    def __enter__(self):
        self._stdout = sys.stdout
        sys.stdout = self._stringio = StringIO()

        self._stringio.close = lambda x: 1
        return self

    def __exit__(self, *args):
        self.extend(self._stringio.getvalue().splitlines())
        del self._stringio
        sys.stdout = self._stdout

def run_test(sample, test=None, debug=False, fail_debug=None):

    reliability_guard()
    _install_sigalrm()

    if debug:
        print(f'start = {datetime.now().time()}')

    try:
        in_outs = json.loads(sample['input_output'])
    except ValueError:
        in_outs = None
    if in_outs:
        if in_outs.get('fn_name') is None:
            which_type = CODE_TYPE.standard_input
            method_name = None
        else:
            which_type = CODE_TYPE.call_based
            method_name = in_outs['fn_name']

    if debug:
        print(f'loaded input_output = {datetime.now().time()}')

    if test is None:
        return in_outs
    elif test is not None:
        n_total_cases = len(in_outs.get('inputs') or []) if in_outs else 0
        ctx = {"index": None, "inputs": None, "expected": None, "output": None, "error": None}
        results = _ResultList(fail_debug, ctx)
        sol = (
            'import sys\nimport time\nimport itertools\n'
            'from itertools import accumulate, product, permutations, combinations, combinations_with_replacement, groupby, islice, cycle, repeat, chain, zip_longest\n'
            'import collections\nfrom collections import Counter, OrderedDict, deque, defaultdict, ChainMap, namedtuple\n'
            'import functools\nfrom functools import lru_cache, reduce, cmp_to_key, partial, cache\n'
            'import math\nfrom math import sqrt, sin, cos, tan, ceil, fabs, floor, gcd, lcm, exp, log, log2, log10, factorial, comb, perm, isqrt, pi, inf, prod, hypot, degrees, radians, atan2, asin, acos, atan\n'
            'import fractions\nfrom fractions import Fraction\n'
            'import decimal\nfrom decimal import Decimal\n'
            'import string\nfrom string import ascii_lowercase, ascii_uppercase, ascii_letters, digits, punctuation, hexdigits\n'
            'import re\nimport bisect\nfrom bisect import bisect_left, bisect_right, bisect, insort, insort_left, insort_right\n'
            'import operator\nfrom operator import itemgetter, attrgetter, mul, add, sub, xor, or_, and_\n'
            'import copy\nfrom copy import copy, deepcopy\n'
            'from typing import List, Tuple, Dict, Set, Optional, Any, Union, Iterable, Callable\n'
            'import numpy as np\nimport random\nimport heapq\nfrom heapq import *\n'
        )
        if debug:
            print(f'loading test code = {datetime.now().time()}')

        if which_type == CODE_TYPE.call_based:
            cleaned_test = _clean_call_based_ast(test)
            sol_clean = sol + cleaned_test
            if debug:
                print(f'sol = {sol_clean}')
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol_clean)
                if 'class Solution' not in cleaned_test:
                    tmp = tmp_sol
                else:
                    tmp = tmp_sol.Solution()
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if cleaned_test != test:
                    signal.alarm(timeout)
                    try:
                        tmp_sol = _runtime_module().from_string('tmp_sol', '', sol + test)
                        tmp = tmp_sol if 'class Solution' not in test else tmp_sol.Solution()
                        signal.alarm(0)
                    except Exception as e2:
                        signal.alarm(0)
                        ctx["error"] = f"compile: {e2!r}"
                        results.append(-2)
                        return results
                else:
                    if debug:
                        print(f'type 0 compilation error = {e}')
                    ctx["error"] = f"compile: {e!r}"
                    results.append(-2)
                    return results
            signal.alarm(0)

        elif which_type == CODE_TYPE.standard_input:
            test_norm = re.sub(
                r"""(?m)^([ \t]*if\s+__name__\s*==\s*['"]__main__['"]\s*:)""",
                lambda m: m.group(1).split("if")[0] + "if True:",
                test,
            )
            tmp_test = test_norm.split('\n')

            new_test = []
            for x in tmp_test:
                if (not x.startswith('from ')) and (
                        not x.startswith('import ')):
                    new_test.append('\t' + x + '\n')
                else:
                    new_test.append(x + '\n')
            tmp_test = new_test

            new_test = ''
            started = False
            for i in tmp_test:
                if i.startswith('\t') and not started:
                    new_test += 'stdin = sys.stdin\nstdout = sys.stdout\n'
                    new_test += 'def code():\n'
                    new_test += i
                    started = True
                elif started and ((i.startswith('from ')) or
                                  (i.startswith('import '))):
                    new_test += '\t' + i
                else:
                    new_test += i
            if not started:
                new_test += 'stdin = sys.stdin\nstdout = sys.stdout\ndef code():\n\tpass\n'
            else:
                new_test += '\n\tpass\n'
            tmp_test = new_test

            sol += tmp_test
            if debug:
                print(f'sol = {sol}')
            method_name = 'code'
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol)
                tmp = tmp_sol
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if debug:
                    print(f'type 1 compilation error = {e}')
                ctx["error"] = f"compile: {e!r}"
                results.append(-2)
                return results
            signal.alarm(0)
        if debug:
            print(f'get method = {datetime.now().time()}')

        try:
            method = getattr(tmp, method_name)
        except Exception:
            signal.alarm(0)
            method = None
            if which_type == CODE_TYPE.call_based:
                try:
                    tree = ast.parse(test)
                    top_funcs = [
                        n.name for n in tree.body
                        if isinstance(n, ast.FunctionDef) and not n.name.startswith('_')
                    ]
                    if top_funcs:
                        cand_name = top_funcs[-1]
                        if hasattr(tmp, cand_name):
                            method = getattr(tmp, cand_name)
                except Exception:
                    method = None
            if method is None:
                e = sys.exc_info()
                if debug:
                    print(f'unable to get function error = {e}')
                ctx["error"] = f"getattr: {e!r}"
                results.append(-2)
                return results

        for index, inputs in enumerate(in_outs['inputs']):
            ctx["index"] = index
            ctx["inputs"] = _clip_debug(inputs)
            ctx["expected"] = _clip_debug(in_outs['outputs'][index])
            ctx["output"] = None
            ctx["error"] = None

            try:
                if isinstance(inputs[0], dict):
                    inputs = [{int(k): v for k, v in inputs[0].items()}]
            except:
                True
            try:
                if isinstance(in_outs['outputs'][index], dict):
                    in_outs['outputs'][index] = [{
                        int(k): v
                        for k, v in in_outs['outputs'][index].items()
                    }]
            except:
                True
            try:
                if isinstance(in_outs['outputs'][index][0], dict):
                    in_outs['outputs'][index] = [{
                        int(k): v
                        for k, v in in_outs['outputs'][index][0].items()
                    }]
            except:
                True

            if debug:
                print(
                    f'time: {datetime.now().time()} testing index = {index}  inputs = {inputs}, {type(inputs)}. type = {which_type}'
                )
            if which_type == CODE_TYPE.call_based:
                signal.alarm(timeout)
                faulthandler.enable()
                try:
                    output = method(*inputs)
                    ctx["output"] = output

                    if isinstance(output, tuple):
                        output = list(output)

                    tmp_result = output == in_outs['outputs'][index]
                    if isinstance(in_outs['outputs'][index],
                                  list) and in_outs['outputs'][index]:
                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index][0])

                    try:
                        if isinstance(output[0], tuple):
                            tmp_result = tmp_result or ([
                                list(x) for x in output
                            ] == in_outs['outputs'][index][0])
                    except:
                        True
                    results.append(tmp_result)

                    signal.alarm(0)
                except Exception as e:
                    signal.alarm(0)
                    faulthandler.disable()
                    if debug:
                        print(
                            f'Standard input runtime error or time limit exceeded error = {e}'
                        )
                    ctx["error"] = f"runtime: {e!r}"
                    results.append(-1)
                    if isinstance(e, TimeoutException):
                        for _ in range(index + 1, n_total_cases):
                            results.append(-1)
                        break
                    continue
                faulthandler.disable()
                signal.alarm(0)
                if debug:
                    print(
                        f"outputs = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                    )
            elif which_type == CODE_TYPE.standard_input:
                faulthandler.enable()
                signal.alarm(timeout)
                passed = False

                if isinstance(inputs, list):
                    inputs = '\n'.join(inputs)
                if isinstance(in_outs['outputs'][index], list):
                    in_outs['outputs'][index] = '\n'.join(
                        in_outs['outputs'][index])

                timed_out = False
                with Capturing() as output:
                    try:
                        call_method(method, inputs)

                        signal.alarm(0)
                        passed = True
                    except Exception as e:

                        signal.alarm(0)
                        if debug:
                            print(
                                f'Call-based runtime error or time limit exceeded error = {repr(e)}{e}'
                            )
                        ctx["error"] = f"runtime: {e!r}"
                        results.append(-1)
                        if isinstance(e, TimeoutException):
                            timed_out = True
                    signal.alarm(0)
                ctx["output"] = list(output)

                if timed_out:
                    for _ in range(index + 1, n_total_cases):
                        results.append(-1)
                    break

                if not passed:
                    if debug:
                        nl = '\n'
                        if not isinstance(inputs, list):
                            print(
                                f"not passed output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs.replace(nl,' new-line ')}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                            )
                        else:
                            print(
