            method_name = None
        else:
            which_type = CODE_TYPE.call_based
            method_name = in_outs['fn_name']

    if debug:
        print(f'loaded input_output = {datetime.now().time()}')

    if test is None:
        return in_outs
    elif test is not None:
        n_total_cases = len(in_outs.get('inputs') or []) if in_outs else 0
        ctx = {"index": None, "inputs": None, "expected": None, "output": None, "error": None}
        results = _ResultList(fail_debug, ctx)
        sol = (
            'import sys\nimport time\nimport itertools\n'
            'from itertools import accumulate, product, permutations, combinations, combinations_with_replacement, groupby, islice, cycle, repeat, chain, zip_longest\n'
            'import collections\nfrom collections import Counter, OrderedDict, deque, defaultdict, ChainMap, namedtuple\n'
            'import functools\nfrom functools import lru_cache, reduce, cmp_to_key, partial, cache\n'
            'import math\nfrom math import sqrt, sin, cos, tan, ceil, fabs, floor, gcd, lcm, exp, log, log2, log10, factorial, comb, perm, isqrt, pi, inf, prod, hypot, degrees, radians, atan2, asin, acos, atan\n'
            'import fractions\nfrom fractions import Fraction\n'
            'import decimal\nfrom decimal import Decimal\n'
            'import string\nfrom string import ascii_lowercase, ascii_uppercase, ascii_letters, digits, punctuation, hexdigits\n'
            'import re\nimport bisect\nfrom bisect import bisect_left, bisect_right, bisect, insort, insort_left, insort_right\n'
            'import operator\nfrom operator import itemgetter, attrgetter, mul, add, sub, xor, or_, and_\n'
            'import copy\nfrom copy import copy, deepcopy\n'
            'from typing import List, Tuple, Dict, Set, Optional, Any, Union, Iterable, Callable\n'
            'import numpy as np\nimport random\nimport heapq\nfrom heapq import *\n'
        )
        if debug:
            print(f'loading test code = {datetime.now().time()}')

        if which_type == CODE_TYPE.call_based:
            cleaned_test = _clean_call_based_ast(test)
            sol_clean = sol + cleaned_test
            if debug:
                print(f'sol = {sol_clean}')
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol_clean)
                if 'class Solution' not in cleaned_test:
                    tmp = tmp_sol
                else:
                    tmp = tmp_sol.Solution()
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if cleaned_test != test:
                    signal.alarm(timeout)
                    try:
                        tmp_sol = _runtime_module().from_string('tmp_sol', '', sol + test)
                        tmp = tmp_sol if 'class Solution' not in test else tmp_sol.Solution()
                        signal.alarm(0)
                    except Exception as e2:
                        signal.alarm(0)
                        ctx["error"] = f"compile: {e2!r}"
                        results.append(-2)
                        return results
                else:
                    if debug:
                        print(f'type 0 compilation error = {e}')
                    ctx["error"] = f"compile: {e!r}"
                    results.append(-2)
                    return results
            signal.alarm(0)

